import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { cpus, platform, release } from 'node:os';
import { performance } from 'node:perf_hooks';
import { execFileSync } from 'node:child_process';
import Typograf from './package/dist/typograf.es.mjs';
import { Typographist } from '/home/alex/projects/elmenov-softworks/typographist/packages/typographist/dist/index.js';
import { Typographist as Baseline } from '/tmp/typographist-symbolic-profile/baseline-dist/index.js';
import { createTypographyWorkloads } from '/home/alex/projects/elmenov-softworks/typographist/tools/benchmarks/typography/workloads.factory.ts';

const root = '/home/alex/projects/elmenov-softworks/typographist';
const inventory = await readFile(root + '/specs/feature/typography/typograf-rule-inventory.md', 'utf8');
const selectedRules = inventory.split('\n').filter(line => /\| (Include|Adapt):/.test(line))
  .map(line => line.match(/`([^`]+)`/)[1]);
const availableRules = new Set(Typograf.getRules().map(rule => rule.name));
for (const id of selectedRules) assert.ok(availableRules.has(id), `Unknown Typograf rule: ${id}`);
const symbolic = ['quotes', 'dashes', 'punctuation', 'nonbreakingSpacing'];
const createReference = (locale, restricted) => {
  const service = new Typograf({ locale: locale === 'en' ? 'en-US' : 'ru' });
  if (restricted) {
    service.disableRule('*');
    service.enableRule(selectedRules);
  }
  return service;
};
const definitions = [
  { id: 'ours-symbolic', create: () => {
    const service = new Typographist({ categories: symbolic, useFast: true, cacheSize: 0,
      settings: { 'common/punctuation/quote': { spacing: false } } });
    return (text, locale) => service.format(text, locale);
  } },
  { id: 'typograf-symbolic', create: () => {
    const services = { en: createReference('en', true), ru: createReference('ru', true) };
    return (text, locale) => services[locale].execute(text);
  } },
  { id: 'typograf-default', create: () => {
    const services = { en: createReference('en', false), ru: createReference('ru', false) };
    return (text, locale) => services[locale].execute(text);
  } },
  { id: 'ours-full-khristov-cache', create: () => {
    const service = new Typographist({ useFast: true, cacheSize: 64 });
    return (text, locale) => service.format(text, locale);
  } },
];
const workloads = createTypographyWorkloads();
definitions.push(
  { id: 'baseline-symbolic', create: () => {
    const service = new Baseline({ categories: symbolic, useFast: true, cacheSize: 0,
      settings: { 'common/punctuation/quote': { spacing: false } } });
    return (text, locale) => service.format(text, locale);
  } },
  { id: 'baseline-full-khristov-cache', create: () => {
    const service = new Baseline({ useFast: true, cacheSize: 64 });
    return (text, locale) => service.format(text, locale);
  } },
);
for (const locale of ['en', 'ru']) {
  const unit = locale === 'en'
    ? 'The "reader" can enjoy typography - a simple sentence... On Monday, see page 12. It\'s helpful. '
    : 'Читатель видит "типографику" - простое предложение... В понедельник см. стр. 12. Это помогает читать. ';
  for (const repetitions of [20, 160, 640]) workloads.push({
    name: `prose-${repetitions}-${locale}`, locale, text: unit.repeat(repetitions),
  });
}
const summarize = samples => {
  const sorted = [...samples].sort((a, b) => a - b);
  return { minMs: sorted[0], medianMs: sorted[Math.floor(sorted.length / 2)], maxMs: sorted.at(-1), samplesMs: samples };
};
let consumedLength = 0;
const results = [];
for (const workload of workloads) {
  const runners = definitions.map(definition => {
    const format = definition.create();
    const expected = format(workload.text, workload.locale);
    for (let warmup = 0; warmup < 10; warmup++) consumedLength += format(workload.text, workload.locale).length;
    return { id: definition.id, format, expected, samples: [] };
  });
  const iterations = Math.max(5, Math.min(50, Math.floor(250000 / workload.text.length)));
  assert.equal(runners[0].expected, runners[4].expected, `Changed symbolic output: ${workload.name}`);
  assert.equal(runners[3].expected, runners[5].expected, `Changed full output: ${workload.name}`);
  for (let sample = 0; sample < 9; sample++) {
    for (let offset = 0; offset < runners.length; offset++) {
      const runner = runners[(sample + offset) % runners.length];
      const start = performance.now();
      let output;
      for (let iteration = 0; iteration < iterations; iteration++) {
        output = runner.format(workload.text, workload.locale);
        consumedLength += output.length;
      }
      runner.samples.push((performance.now() - start) / iterations);
      assert.equal(output, runner.expected);
    }
  }
  results.push({ name: workload.name, locale: workload.locale, inputUtf16: workload.text.length,
    inputSha256: createHash('sha256').update(workload.text).digest('hex'), iterations,
    equalSymbolicOutput: runners[0].expected === runners[1].expected,
    measurements: runners.map(runner => ({ id: runner.id, outputUtf16: runner.expected.length,
      outputSha256: createHash('sha256').update(runner.expected).digest('hex'), ...summarize(runner.samples) })),
  });
  console.log(workload.name, JSON.stringify(results.at(-1).measurements.map(({ id, medianMs }) => ({ id, medianMs }))));
}
const report = {
  createdAt: new Date().toISOString(), sourceCommit: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(),
  workingTree: execFileSync('git', ['status', '--short'], { cwd: root, encoding: 'utf8' }).trim(),
  node: process.version, cpu: cpus()[0]?.model, os: `${platform()} ${release()}`, typografVersion: '7.8.0',
  typografTarballSha256: createHash('sha256').update(await readFile('/tmp/typograf-7.8.0.tgz')).digest('hex'),
  baselineCommit: '9cbda8622f7fa26a206865f578151b933db7fa00',
  exactBaselineEquivalence: 'Symbolic and full optimized outputs equal their baseline outputs for every workload.',
  sourceFileSha256: Object.fromEntries(await Promise.all([
    'rules/rules-registry.ts', 'text/scanning/scan-addresses.util.ts',
    'text/typography/bundled-dashes.factory.ts', 'text/typography/bundled-quotes.factory.ts',
    'text/typography/prepare-text-pipeline.util.ts',
  ].map(async path => [path, createHash('sha256').update(await readFile(root + '/packages/typographist/src/' + path)).digest('hex')]))),
  harnessSource: await readFile(new URL(import.meta.url), 'utf8'),
  procedure: 'Fresh core build. Node only, no browser. One formatter per workload and profile, created outside timing. Both locales are registered. Ten warmup calls, nine rotated-order batches; times divided by batch iterations. Each call receives original input. Output determinism asserted outside timing. Cache is warmed only for full Khristov profile. No output-equivalence claim: enabled groups are similar but rule behavior differs. Ours-symbolic disables quote spacing and hyphenation; Typograf symbolic enables only Include/Adapt IDs from current owner inventory, including normally disabled afterNumber. Default Typograf performs additional cleanup/content conversion; full Typographist adds hyphenation and default quotation spacing. Construction, imports, downloads and I/O excluded. Results include JIT, GC and machine-load noise.',
  categories: symbolic, selectedTypografRules: selectedRules, workloads, consumedLength, results,
};
const output = root + '/specs/feature/typography/benchmarks/typograf-optimized';
await writeFile(output + '.json', JSON.stringify(report, null, 2) + '\n');
const labels = ['Ours: symbolic (optimized)', 'Typograf: selected rules', 'Typograf: defaults', 'Ours: full (optimized)', 'Ours: symbolic (baseline)', 'Ours: full (baseline)'];
const colors = ['#2563eb', '#16a34a', '#d97706', '#9333ea', '#64748b', '#b91c1c'];
const charts = results.map(result => {
  const max = Math.max(...result.measurements.map(value => value.medianMs));
  return `<section><h2>${result.name} (${result.inputUtf16} UTF-16 units)</h2>` + result.measurements.map((value, i) =>
    `<div class="row"><span>${labels[i]}</span><div class="track"><div style="width:${value.medianMs / max * 100}%;background:${colors[i]}"></div></div><b>${value.medianMs.toFixed(3)} ms</b></div>`).join('') + '</section>';
}).join('');
await writeFile(output + '.html', `<!doctype html><html lang="en"><meta charset="utf-8"><title>Typographist vs Typograf</title><style>body{font:16px system-ui;max-width:1000px;margin:40px auto;padding:0 20px;color:#172033;background:#f8fafc}section{background:white;padding:20px;margin:20px 0;border:1px solid #ddd;border-radius:8px}h2{font-size:18px}.row{display:grid;grid-template-columns:270px 1fr 100px;gap:12px;align-items:center;margin:12px 0}.track{background:#eef2f7;height:18px}.track div{height:100%}b{text-align:right;font-size:14px}</style><h1>Typographist vs Typograf 7.8.0</h1><p>Node ${report.node}; ${report.cpu}. Nine batches after ten warmups; medians per call. Lower is faster. Bars share a scale within each workload.</p><p>Selected rules are close in scope, but outputs differ. Typograf defaults perform extra cleanup; full Typographist adds hyphenation. Quote spacing is disabled only for our symbolic profile. Construction is excluded.</p>${charts}<p><a href="typograf-optimized.json">Raw inputs, settings and timing samples</a></p></html>\n`);
